-- Revision cards for one book, series, level, term, and unit.
-- Paths point at files already on the site. Video is optional and starts empty.
-- Students read lesson_cards_live. Draft text stays on the base table.

create table public.lesson_cards (
  id bigint generated always as identity primary key,
  book text not null,
  series text not null,
  term text not null,
  level text not null,
  unit_id text not null,
  n integer not null check (n > 0),
  en text not null default '',
  syllables text not null default '',
  zh text not null default '',
  pos text not null default '',
  ex_en text not null default '',
  ex_zh text not null default '',
  adv_en text not null default '',
  adv_zh text not null default '',
  highlight text not null default '',
  img text not null default '',
  audio text not null default '',
  video text not null default '',
  published jsonb,
  status text not null default 'draft',
  updated_at timestamptz not null default now(),
  constraint lesson_cards_book_check check (book in ('oxford', 'longman')),
  constraint lesson_cards_series_check check (
    (book = 'oxford' and series = 'oxford')
    or (book = 'longman' and series in ('mypearson-express', 'elect'))
  ),
  constraint lesson_cards_term_check check (term in ('first', 'second')),
  constraint lesson_cards_level_check check (level in ('p1', 'p2', 'p3', 'p4', 'p5', 'p6')),
  constraint lesson_cards_unit_check check (unit_id in ('unit1', 'unit2', 'unit3', 'unit4', 'dictation3')),
  constraint lesson_cards_status_check check (status in ('draft', 'published')),
  constraint lesson_cards_place_key unique (book, series, term, level, unit_id, n)
);

create index lesson_cards_lookup
  on public.lesson_cards (book, series, term, level, unit_id, status);

create or replace function public.lesson_cards_touch()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

create trigger lesson_cards_touch
  before update on public.lesson_cards
  for each row execute function public.lesson_cards_touch();

create table private.content_editors (
  user_id uuid primary key references auth.users (id) on delete cascade
);

insert into private.content_editors (user_id)
select id from public.profiles
where username in ('keroro3a22', 'keroroa22')
on conflict (user_id) do nothing;

create or replace function public.is_content_editor()
returns boolean
language sql
stable
security definer
set search_path = public, private
as $$
  select exists (
    select 1 from private.content_editors
    where user_id = auth.uid()
  );
$$;

grant execute on function public.is_content_editor() to anon, authenticated;

alter table public.lesson_cards enable row level security;

create policy lesson_cards_editor_all
  on public.lesson_cards
  for all
  to authenticated
  using (public.is_content_editor())
  with check (public.is_content_editor());

create or replace view public.lesson_cards_live
with (security_invoker = false) as
select
  book, series, term, level, unit_id, n,
  published->>'en' as en,
  published->>'syllables' as syllables,
  published->>'zh' as zh,
  published->>'pos' as pos,
  published->>'ex_en' as ex_en,
  published->>'ex_zh' as ex_zh,
  published->>'adv_en' as adv_en,
  published->>'adv_zh' as adv_zh,
  published->>'highlight' as highlight,
  published->>'audio' as audio,
  published->>'img' as img,
  coalesce(published->>'video', '') as video
from public.lesson_cards
where status = 'published'
  and published is not null;

revoke all on public.lesson_cards from anon, authenticated;
grant select on public.lesson_cards_live to anon, authenticated;
grant select, insert, update, delete on public.lesson_cards to authenticated;
grant usage, select on sequence public.lesson_cards_id_seq to authenticated;

